26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    private String telephone;
49	
50	    @Column(name = "email")
51	    private String email;
52	
53	    @Column(name = "postcode")
54	    private String postcode;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "namesake_count")
63	    private Integer namesakeCount;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    public String getEmail() {
69	        return this.email;
70	    }
71	
72	    public void setEmail(String email) {
73	        this.email = email == null ? null : email.toLowerCase(Locale.ENGLISH);
74	    }
75	
76	    public String getAddress() {
77	        return this.address;
78	    }
79	
80	    public void setAddress(String address) {
81	        this.address = AddressNormalizer.normalize(address);
82	    }
83	
84	    public String getPostcode() {
85	        return this.postcode;
86	    }
87	
88	    public void setPostcode(String postcode) {
89	        this.postcode = postcode;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = E164.toE164(telephone);
106	    }
107	
108	    public LocalDate getRegistrationDate() {
109	        return this.registrationDate;
110	    }
111	
112	    public void setRegistrationDate(LocalDate registrationDate) {
113	        this.registrationDate = registrationDate;
