118	    }
119	
120	    public void setCustomerCode(String customerCode) {
121	        this.customerCode = customerCode;
122	    }
123	
124	    public Integer getNamesakeCount() {
125	        return this.namesakeCount;
126	    }
127	
128	    public void setNamesakeCount(Integer namesakeCount) {
129	        this.namesakeCount = namesakeCount;
130	    }
131	
132	    protected Set<Pet> getPetsInternal() {
133	        if (this.pets == null) {
134	            this.pets = new HashSet<>();
135	        }
136	        return this.pets;
137	    }
138	
139	    protected void setPetsInternal(Set<Pet> pets) {
140	        this.pets = pets;
141	    }
142	
143	    public List<Pet> getPets() {
144	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
145	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
146	        return Collections.unmodifiableList(sortedPets);
147	    }
148	
149	    public void setPets(List<Pet> pets) {
150	        this.pets = new HashSet<>(pets);
151	    }
152	
153	    public void addPet(Pet pet) {
154	        getPetsInternal().add(pet);
155	        pet.setOwner(this);
156	    }
157	
158	    /**
159	     * Return the Pet with the given name, or null if none found for this Owner.
160	     *
161	     * @param name to test
162	     * @return true if pet name is already in use
163	     */
164	    public Pet getPet(String name) {
165	        return getPet(name, false);
166	    }
167	
168	    /**
169	     * Return the Pet with the given name, or null if none found for this Owner.
170	     *
171	     * @param name to test
172	     * @return true if pet name is already in use
173	     */
174	    public Pet getPet(String name, boolean ignoreNew) {
175	        name = name.toLowerCase();
176	        for (Pet pet : getPetsInternal()) {
177	            if (!ignoreNew || !pet.isNew()) {
178	                String compName = pet.getName();
179	                compName = compName.toLowerCase();
180	                if (compName.equals(name)) {
181	                    return pet;
182	                }
183	            }
184	        }
185	        return null;
186	    }
187	
188	    public Pet getPet(Integer petId) {
189	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
190	    }
191	
192	    @Override
193	    public String toString() {
194	        return new ToStringCreator(this)
195	
196	            .append("id", this.getId())
197	            .append("new", this.isNew())
198	            .append("lastName", this.getLastName())
199	            .append("firstName", this.getFirstName())
200	            .append("address", this.address)
201	            .append("city", this.city)
202	            .append("telephone", this.telephone)
203	            .toString();
204	    }
205	}
